message.content:
{
  "description": "The creature is a large quadrupedal animal shown in side profile facing right. It has the head, fur, and paws of a brown bear combined with a heavy, glossy, segmented exoskeleton that covers the back, sides, neck, and outer surfaces of all four legs. The exoskeleton is dark brown and shiny on top with overlapping plates, and lighter tan underneath on the belly and chest. A single long, glossy black, curved horn projects from the center of the forehead. The animal stands on four thick legs ending in clawed paws, and has a short, narrow, segmented tail at the rear. The overall appearance is a bear-like mammal encased in woodlouse or isopod-like armor.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like, covered in dense shaggy brown fur with a lighter tan muzzle, a large black nose at the tip, small brown eyes, and fine whiskers on the muzzle; located at the front of the body",
      "where": "front of body, in front of the armored neck"
    },
    {
      "part": "horns",
      "looks_like": "single large glossy black horn, long and strongly curved upward and backward with a small pointed notch on the inner curve and a ridged texture near the tip",
      "where": "projecting from the center of the forehead between the ears"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears covered in short brown fur, with slightly darker edges",
      "where": "on top of the head, one on each side of the base of the horn"
    },
    {
      "part": "mane",
      "looks_like": "thick shaggy brown fur forming a ruff around the neck and chest, longer than the fur on the head",
      "where": "around the neck between the head and the dark neck plates, and on the lower chest and leg joints"
    },
    {
      "part": "legs",
      "looks_like": "four thick, sturdy legs, mostly covered in overlapping glossy dark brown plates with patches of brown fur visible at the joints and near the paws; the plates are segmented into bands around each leg",
      "where": "underneath the body, two in front and two in back supporting the animal"
    },
    {
      "part": "feet",
      "looks_like": "four broad paws covered in brown fur with five long, curved, dark gray-black claws on each paw, with visible paw pads and fur between the toes",
      "where": "at the ends of the four legs, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "short, narrow, tapering tail covered in small overlapping dark brown segmented plates, pointed at the tip",
      "where": "at the rear end of the body, extending from under the last dorsal plates"
    },
    {
      "part": "shell",
      "looks_like": "extensive glossy carapace of overlapping dark brown plates covering the back, sides, shoulders, hips, and neck, with a large smooth shoulder plate and smaller banded plates behind it",
      "where": "covering the dorsal and lateral surfaces of the torso and neck"
    },
    {
      "part": "plates",
      "looks_like": "glossy dark brown dorsal plates with light wear marks and rows of small circular pits, and lighter tan ventral plates on the belly and inner legs with rows of oval holes and smaller circular holes",
      "where": "dorsal plates across the back and sides, ventral plates on the belly, chest, and between the legs, and banded plates encircling each leg"
    },
    {
      "part": "markings",
      "looks_like": "rows of small oval and circular holes (spiracles) arranged in lines along the side plates and on the light tan belly plates",
      "where": "along the lower edge of the dark side plates and across the tan ventral plates on the sides and belly"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "rhinoceros beetle",
    "woodlouse"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
